const paperLength = PaperLength?.value || 0;
const productLength = ProductLength?.value || 0;
const productCount = ProductCount?.value || 0;

let count = 0;

if (productLength > 0) {
  count = paperLength / productLength;
}

count = Number(count.toFixed(2));

asset.set(ProductCount.path, count);

send(msg);

const raw = Number(EncoderRawValue?.value ?? 0);
const prevRaw = Number(EncoderPrevRaw?.value ?? 0);
const prevRawPath = EncoderPrevRaw?.path ?? "";
const machineSpeedPath = MachineSpeed?.path ?? "";

// counter paths
const setupPath = PaperConsumedSetup?.path ?? "";
const idlePath = PaperConsumedIdle?.path ?? "";
const prodPath = PaperConsumedProduction?.path ?? "";
const wastePath = PaperWaste?.path ?? "";
const totalConsumedPath = PaperTotalConsumed?.path ?? "";
const jobActivityCategory = JobActivityCategoryAttribute?.value ?? "";

if (!prevRawPath) { send(msg); return; }

// hitung delta (normal naik -> selisih, reset turun -> raw)
const delta = raw >= prevRaw ? (raw - prevRaw) : raw;

if (!Number.isFinite(delta) || delta < 0) {
  asset.set(prevRawPath, raw);
  send(msg);
  return;
}

// ===== SPEED =====
// 1 pulse = 0.1 m, update tiap 1 detik => m/min = delta * 0.1 * 60 = delta * 6
const speedMpm = delta * 6;

// kalau mau 0 speed saat delta=0 juga ke-set
if (machineSpeedPath) asset.set(machineSpeedPath, speedMpm);

// kalau delta = 0, skip konsumsi kertas tapi prevRaw tetap update
if (delta === 0) {
  asset.set(prevRawPath, raw);
  send(msg);
  return;
}

// baca nilai sebelumnya
const setupPrev = Number(PaperConsumedSetup?.value ?? 0);
const idlePrev = Number(PaperConsumedIdle?.value ?? 0);
const prodPrev = Number(PaperConsumedProduction?.value ?? 0);

let setupNew = setupPrev;
let idleNew = idlePrev;
let prodNew = prodPrev;

// routing delta ke jobActivityCategory
if (jobActivityCategory === "Setup") setupNew += delta;
else if (jobActivityCategory === "Idle") idleNew += delta;
else if (jobActivityCategory === "Production") prodNew += delta;
else helpers.log("no activity");

// set counters kalau path tersedia
if (setupPath) asset.set(setupPath, setupNew);
if (idlePath) asset.set(idlePath, idleNew);
if (prodPath) asset.set(prodPath, prodNew);

// waste & total
const waste = setupNew + idleNew;
const totalConsumed = waste + prodNew;

if (wastePath) asset.set(wastePath, waste);
if (totalConsumedPath) asset.set(totalConsumedPath, totalConsumed);

// simpan raw terakhir
asset.set(prevRawPath, raw);

send(msg);

// ===== INPUT =====
const rawMode = String(JobActivityCategoryAttribute?.value ?? "")
  .trim()
  .toLowerCase();

// ===== OUTPUT PATHS =====
const setupPath = SetupDurationSec?.path ?? "";
const idlePath = IdleDurationSec?.path ?? "";
const prodPath = ProductionDurationSec?.path ?? "";

if (!setupPath || !idlePath || !prodPath) {
  send(msg);
  return;
}

// ===== AMBIL NILAI SEBELUMNYA =====
let setupTime = Number(SetupDurationSec?.value ?? 0);
let idleTime = Number(IdleDurationSec?.value ?? 0);
let prodTime = Number(ProductionDurationSec?.value ?? 0);

// ===== IDENTIFIKASI MODE (support Setup/X dll) =====
let mode = "";

if (rawMode.startsWith("setup")) mode = "setup";
else if (rawMode.startsWith("idle")) mode = "idle";
else if (rawMode.startsWith("production")) mode = "production";

// ===== TAMBAH 1 DETIK SESUAI MODE =====
if (mode === "setup") setupTime += 1;
else if (mode === "idle") idleTime += 1;
else if (mode === "production") prodTime += 1;

// ===== SIMPAN =====
asset.set(setupPath, setupTime);
asset.set(idlePath, idleTime);
asset.set(prodPath, prodTime);

send(msg);

